using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Tools the agent can invoke
// ---------------------------------------------------------------------------
var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearch.SearchAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// ---------------------------------------------------------------------------
// Build the chat client with automatic function-calling support
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// System prompt
// ---------------------------------------------------------------------------
var systemPrompt = """
    You are a research agent. When the user gives you a topic:
    1. Use the web_search tool multiple times with different queries to gather
       information from various angles.
    2. As you find useful facts, save them with the add_note tool.
    3. After you have gathered enough information, call get_notes to review
       everything you collected.
    4. Finally, write a well-structured summary of your findings for the user.
    Be thorough — search at least 3 different queries before summarising.
    """;

var history = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
};

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔═══════════════════════════════════════════╗");
Console.WriteLine("║        🔍  Research Agent  (AI)           ║");
Console.WriteLine("║  Enter a topic to research, or 'quit'.   ║");
Console.WriteLine("╚═══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Topic> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();
    history.Add(new ChatMessage(ChatRole.User, $"Research the following topic: {input}"));

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching — this may take a moment…\n");
    Console.ResetColor();

    var response = await client.GetResponseAsync(history, chatOptions);

    // Append assistant reply to history so the conversation continues naturally.
    foreach (var msg in response.Messages)
        history.Add(msg);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine(response.Text);
    Console.ResetColor();
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// ═══════════════════════════════════════════════════════════════════════════
// Tool implementations
// ═══════════════════════════════════════════════════════════════════════════

/// <summary>Simulated web-search tool the agent can call.</summary>
static class WebSearch
{
    private static readonly HttpClient Http = new();

    [Description("Search the web for a query and return a snippet of results.")]
    public static async Task<string> SearchAsync(
        [Description("The search query string")] string query)
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine($"  🌐 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required).
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await Http.GetStringAsync(url);

            // Pull out the abstract / related topics for a useful snippet.
            using var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            var parts = new List<string>();

            if (root.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
                parts.Add($"Summary: {abstractText}");

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                        parts.Add($"- {t}");
                }
            }

            return parts.Count > 0
                ? string.Join("\n", parts)
                : $"No detailed results found for \"{query}\". Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed ({ex.Message}). Try a different query.";
        }
    }
}

/// <summary>Note-taking tool so the agent can collect facts during research.</summary>
class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save a research note or key finding for later reference.")]
    public string AddNote([Description("The note text to save")] string note)
    {
        _notes.Add(note);

        Console.ForegroundColor = ConsoleColor.Magenta;
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        Console.ResetColor();

        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }

    public void Clear() => _notes.Clear();
}

